	for i := range fixture.plan.Peers {
		fixture.plan.Peers[i].ManifestSHA256 = digestWire(fixture.manifests[fixture.plan.Peers[i].Slot])
	}
	payload, err := trust.EncodePayload(fixture.plan)
	if err != nil {
		t.Fatal(err)
	}
	planEnvelope, err := trust.Sign(payload, trust.Scope{Domain: bootstrap.FounderPlanDomain,
		DeploymentID: "0000000000F9PR1WNVDTEXS31Z", Cell: "GRU", Environment: "production", Role: "controller", Slot: "seed-a"},
		fixture.now.Add(-time.Minute), fixture.now.Add(22*time.Hour), fixture.root)
	if err != nil {
		t.Fatal(err)
	}
	fixture.planWire, err = trust.EncodeEnvelope(planEnvelope)
	if err != nil {
		t.Fatal(err)
	}
	fixture.selection.PlanSHA256 = digestWire(fixture.planWire)
	fixture.selection.AnchorSHA256 = digestWire(fixture.anchorWire)
	for i := range fixture.selection.Manifests {
		fixture.selection.Manifests[i].SHA256 = digestWire(fixture.manifests[fixture.selection.Manifests[i].Slot])
	}
	selectedWire := fixture.publish(t, fixture.selection)
	if err := fixture.floor.Initialize(fixture.selection.Generation, digestWire(selectedWire)); err != nil {
		t.Fatal(err)
	}
	current, err := fixture.reader(t).ReadCurrent(t.Context(), fixture.now)
	if err != nil {
		t.Fatal(err)
	}
	directory := filepath.Join(t.TempDir(), "signers")
	if err := os.Mkdir(directory, 0o700); err != nil {
		t.Fatal(err)
	}
	for name, key := range map[string]ed25519.PrivateKey{"founder-peer.key": peerKey, "founder-ledger.key": ledgerKey} {
		if err := os.WriteFile(filepath.Join(directory, name), key, 0o600); err != nil {
			t.Fatal(err)
		}
	}
	return &founderSignerFixture{founderSelectionFixture: fixture, peerKey: peerKey, ledgerKey: ledgerKey,
		store: FounderSignerStore{directory: directory, uid: uint32(os.Getuid()), gid: uint32(os.Getgid()),
			allowUnsafeAncestors: true}, current: current}
}

// FounderSignerStore reads only the signed seed's installed 0600 material.
// Production uses the admission-owned fixed directory and service UID/GID.
type FounderSignerStore struct {
	directory            string
	uid                  uint32
	gid                  uint32
	allowUnsafeAncestors bool
}

func NewFounderSignerStore(serviceUID, serviceGID uint32) (FounderSignerStore, error) {
	if serviceUID == 0 || serviceGID == 0 {
		return FounderSignerStore{}, ErrFounderSigner
	}
	return FounderSignerStore{directory: MaterialDirectory, uid: serviceUID, gid: serviceGID}, nil
}

// FounderSigningKeys holds distinct delegated keys for peer receipt and
// bootstrap ledger records. The caller must close it after each transition.
type FounderSigningKeys struct {
	peer   ed25519.PrivateKey
	ledger ed25519.PrivateKey
}

func (keys *FounderSigningKeys) Close() {
	if keys == nil {
		return
	}
	clear(keys.peer)
	clear(keys.ledger)
	keys.peer = nil
	keys.ledger = nil
}

func (store FounderSignerStore) Load(current CurrentFounderAuthority, accepted AcceptedInstall,
	roots trust.Keyring, now time.Time,
) (FounderSigningKeys, error) {
	return store.LoadContext(context.Background(), current, accepted, roots, now)
}

func (store FounderSignerStore) LoadContext(ctx context.Context, current CurrentFounderAuthority, accepted AcceptedInstall, roots trust.Keyring, now time.Time) (FounderSigningKeys, error) {
	if accepted.validate() != nil || current.Plan == nil || !current.Plan.IsVerified() || !current.Anchor.IsVerified() ||
		len(roots) == 0 || now.IsZero() || now.Location() != time.UTC ||
		!now.Before(current.SelectionExpiresAt) {
		return FounderSigningKeys{}, ErrFounderSigner
	}
	plan := current.Plan.Plan()
	anchor := current.Anchor.Anchor()
	if plan.SeedSlot != accepted.Slot || plan.SeedManifestSHA256 != accepted.ManifestSHA256 ||
		plan.DeploymentID != accepted.DeploymentID || string(plan.Cell) != accepted.Cell ||
		anchor.ClusterID == "" || plan.AnchorSHA256 != current.Anchor.Digest() {
		return FounderSigningKeys{}, ErrFounderSigner
	}
	seed, err := verifiedFounderManifestContext(ctx, current, accepted.Slot, roots, now)
	if err != nil || seed.Digest() != accepted.ManifestSHA256 {
		return FounderSigningKeys{}, fmt.Errorf("%w: selected accepted seed manifest: %v", ErrFounderSigner, err)
	}
	manifest := seed.Manifest()
	peerReference, err := exactSeedSignerReference(manifest, bootstrap.SecretSeedFounder)
	if err != nil {
		return FounderSigningKeys{}, err
	}
	ledgerReference, err := exactSeedSignerReference(manifest, bootstrap.SecretSeedLedgerSigner)
	if err != nil {
		return FounderSigningKeys{}, err
	}
	if current.Derived != nil {
		return store.loadDerivedKeys(ctx, *current.Derived, accepted, peerReference, ledgerReference, now)
	}
	ledgerGrant, err := current.Anchor.LedgerDelegation()
	if err != nil {
		return FounderSigningKeys{}, fmt.Errorf("%w: selected ledger delegation: %v", ErrFounderSigner, err)
	}
	var peerKeyID string
	for _, row := range plan.Peers {
		peerManifest, err := verifiedFounderManifest(current, row.Slot, roots, now)
		if err != nil || peerManifest.Digest() != row.ManifestSHA256 {
			return FounderSigningKeys{}, fmt.Errorf("%w: selected peer manifest %q: %v", ErrFounderSigner, row.Slot, err)
		}
		peerDelegation := peerManifest.Manifest().PeerReceiptDelegation
		if peerDelegation == nil {
			return FounderSigningKeys{}, ErrFounderSigner
		}
		verified, err := trust.VerifyDelegationCurrent(*peerDelegation, roots, now, bootstrap.ManifestTrustPolicy())
		if err != nil || peerKeyID != "" && peerKeyID != verified.SubjectKeyID() {
			return FounderSigningKeys{}, fmt.Errorf("%w: peer receipt delegations differ or expired: %v", ErrFounderSigner, err)
		}
		peerKeyID = verified.SubjectKeyID()
	}
	if peerKeyID == "" || peerKeyID == ledgerGrant.SubjectKeyID() {
		return FounderSigningKeys{}, fmt.Errorf("%w: receipt and ledger signing roles require distinct delegated keys", ErrFounderSigner)
	}
	fd, err := openMaterialDirectory(store.directory, store.uid, store.gid, 0o700, store.allowUnsafeAncestors)
	if err != nil {
		return FounderSigningKeys{}, fmt.Errorf("%w: open installed seed material: %v", ErrFounderSigner, err)
	}
	defer unix.Close(fd)
	peerKey, err := store.readKey(fd, peerReference, accepted.MaterialSHA256, peerKeyID)
	if err != nil {
		return FounderSigningKeys{}, err
	}
	ledgerKey, err := store.readKey(fd, ledgerReference, accepted.MaterialSHA256, ledgerGrant.SubjectKeyID())
	if err != nil {
		clear(peerKey)
		return FounderSigningKeys{}, err
	}
	return FounderSigningKeys{peer: peerKey, ledger: ledgerKey}, nil
}

func exactSeedSignerReference(manifest bootstrap.Manifest, purpose bootstrap.SecretPurpose) (bootstrap.SecretReference, error) {
	var selected bootstrap.SecretReference
	count := 0
	for _, reference := range manifest.Secrets {
		if reference.Purpose == purpose {
			if reference.Slot != manifest.SeedSlot {
				return bootstrap.SecretReference{}, ErrFounderSigner
			}
			selected = reference
			count++
		}
	}
	if count != 1 {
		return bootstrap.SecretReference{}, ErrFounderSigner
	}
	return selected, nil
}

func (store FounderSignerStore) readKey(fd int, reference bootstrap.SecretReference,
	installed map[string]string, delegatedKeyID string,
) (ed25519.PrivateKey, error) {
	if installed[reference.TargetFile] != reference.SHA256 {
		return nil, fmt.Errorf("%w: installed material digest differs from seed manifest", ErrFounderSigner)
	}
	wire, err := readMaterial(fd, reference.TargetFile, store.uid, store.gid, reference.SHA256, reference.MaxBytes)
	if err != nil {
		return nil, fmt.Errorf("%w: read exact installed signer: %v", ErrFounderSigner, err)
	}
	defer clear(wire)
	if len(wire) != ed25519.PrivateKeySize ||
		!bytes.Equal(ed25519.NewKeyFromSeed(wire[:ed25519.SeedSize]), wire) {
		return nil, ErrFounderSigner
	}
	key := ed25519.PrivateKey(bytes.Clone(wire))
	keyID, err := trust.KeyID(key.Public().(ed25519.PublicKey))
	if err != nil || keyID != delegatedKeyID {
		clear(key)
		return nil, fmt.Errorf("%w: installed signer key differs from current root delegation", ErrFounderSigner)
	}
	return key, nil
}

func verifiedFounderManifest(current CurrentFounderAuthority, slot string, roots trust.Keyring,
	now time.Time,
) (bootstrap.StartupAuthority, error) {
	return verifiedFounderManifestContext(context.Background(), current, slot, roots, now)
}

func verifiedFounderManifestContext(ctx context.Context, current CurrentFounderAuthority, slot string, roots trust.Keyring, now time.Time) (bootstrap.StartupAuthority, error) {
	if current.Derived != nil {
		authority, ok := current.Derived.Authority(slot)
		if !ok {
			return nil, ErrFounderSigner
		}
		if err := authority.VerifyCurrent(ctx, now); err != nil {
			return nil, err
		}
		return authority, nil
	}
	wire := current.ManifestWires[slot]
	if len(wire) == 0 || !slices.Contains(current.Plan.Plan().ControllerSlots, slot) {
		return nil, ErrFounderSigner
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return nil, err
	}
	manifest, err := bootstrap.ManifestPayload(envelope.Payload)
	if err != nil {
		return nil, err
	}
	expected, err := current.Anchor.ManifestExpectation(slot, manifest.ImageOCID)
	if err != nil {
		return nil, err
	}
	return bootstrap.VerifyManifest(envelope, roots, expected, now, bootstrap.ManifestTrustPolicy())
}

func readMaterial(dir int, name string, uid, gid uint32, want string, maximum int64) ([]byte, error) {
	if !markerNameRE.MatchString(name) || !markerDigestRE.MatchString(want) || maximum <= 0 || maximum > bootstrap.MaxSecretBytes {
		return nil, ErrMaterial
	}
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != 0o600 || stat.Nlink != 1 ||
		stat.Size <= 0 || stat.Size > maximum {
		return nil, ErrMaterial
	}
	content, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil || len(content) == 0 || int64(len(content)) > maximum || digest(content) != want {
		clear(content)
		return nil, ErrMaterial
	}
	return content, nil
}

func openMaterialDirectory(path string, uid, gid uint32, mode uint32, allowUnsafeAncestors bool) (int, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return -1, ErrMaterial
	}
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return -1, err
	}
	components := strings.Split(strings.TrimPrefix(path, "/"), "/")
	for index, component := range components {
		if component == "" || component == "." || component == ".." {
			unix.Close(fd)
			return -1, ErrMaterial
		}
		next, err := unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
		unix.Close(fd)
		if err != nil {
			return -1, err
		}
		fd = next
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil ||
			index < len(components)-1 && !allowUnsafeAncestors && (stat.Uid != 0 || stat.Mode&0o022 != 0) {
			unix.Close(fd)
			return -1, ErrMaterial
		}
	}
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != mode {
		unix.Close(fd)
		return -1, ErrMaterial
	}
	return fd, nil
}

func RunAdmittedFounder(ctx context.Context, baked BakedInputs, accepted AcceptedInstall,
	serviceUID, serviceGID uint32,
) error {
	return runAdmittedFounder(ctx, baked, accepted, serviceUID, serviceGID, nil, completedAdmittedFounder,
		NewIMDSClient().FetchPlacement)
}

func runAdmittedFounder(ctx context.Context, baked BakedInputs, accepted AcceptedInstall,
	serviceUID, serviceGID uint32, floor *FounderSelectionFloorStore,
	completed func(context.Context, BakedInputs, AcceptedInstall) (bool, error),
	placement func(context.Context) (bootstrap.ControllerPlacement, error),
) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if accepted.validate() != nil || accepted.DeploymentID != baked.Identity.DeploymentID ||
		accepted.Cell != string(baked.Identity.Cell) || serviceUID == 0 || serviceGID == 0 {
		return ErrFounderRuntime
	}
	if accepted.Slot != accepted.SeedSlot {
		return nil
	}

func NewIMDSClient() IMDSClient {
	dialer := &net.Dialer{Timeout: imdsTimeout}
	transport := &http.Transport{
		Proxy: nil, DisableKeepAlives: true, ResponseHeaderTimeout: imdsTimeout,
		DialContext: func(ctx context.Context, network, address string) (net.Conn, error) {
			if network != "tcp" || address != imdsAddress {
				return nil, ErrInvalidDescriptor
			}
			return dialer.DialContext(ctx, network, imdsAddress)
		},
	}
	return IMDSClient{client: &http.Client{
		Timeout: imdsTimeout, Transport: transport,
		CheckRedirect: func(*http.Request, []*http.Request) error { return ErrInvalidDescriptor },
	}}
}

func (marker AcceptedInstall) validate() error {
	if marker.SchemaVersion != 1 || marker.HeadAttempt == 0 || marker.HeadGeneration == 0 ||
		!markerDigestRE.MatchString(marker.AnchorSHA256) || !markerDigestRE.MatchString(marker.ManifestSHA256) ||
		!markerDigestRE.MatchString(marker.ReceiptSHA256) || !markerDigestRE.MatchString(marker.ImageReceiptSHA256) ||
		!markerDigestRE.MatchString(marker.ResultSHA256) || !markerDigestRE.MatchString(marker.BinarySHA256) ||
		marker.DeploymentID == "" || marker.Cell == "" || !descriptorSlotRE.MatchString(marker.Slot) ||
		!descriptorSlotRE.MatchString(marker.SeedSlot) ||
		!strings.HasPrefix(marker.ImageOCID, "ocid1.image.") || !strings.HasPrefix(marker.InstanceOCID, "ocid1.instance.") ||
		!strings.HasPrefix(marker.PrimaryVNICOCID, "ocid1.vnic.") || !validPrivateIPv4(marker.PrimaryPrivateIP) ||
		len(marker.MaterialSHA256) == 0 || len(marker.MaterialSHA256) > 64 ||
		marker.AcceptedAt.IsZero() || marker.AcceptedAt.Location() != time.UTC {
		return ErrInvalidMarker
	}
	for name, digest := range marker.MaterialSHA256 {
		if !markerNameRE.MatchString(name) || !markerDigestRE.MatchString(digest) {
			return ErrInvalidMarker
		}
	}
	if marker.ManagedMaterial != nil && marker.ManagedMaterial.Validate() != nil {
		return ErrInvalidMarker
	}
	return nil
}

func validPrivateIPv4(value string) bool {
	address, err := netip.ParseAddr(value)
	return err == nil && address.Is4() && address.IsGlobalUnicast() && address.String() == value
}

